insert into drabornseries.dbs_video_assets(episode_id,provider,demo_url,ready) select e.id,'demo',case when s.slug='sintel' then 'https://storage.googleapis.com/gtv-videos-bucket/sample/Sintel.mp4' else 'https://storage.googleapis.com/gtv-videos-bucket/sample/BigBuckBunny.mp4' end,true from drabornseries.dbs_episodes e join drabornseries.dbs_series s on s.id=e.series_id where s.is_demo on conflict do nothing;
